// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a non-admin caller (any address other than the deployer)
        address nonAdmin = address(0x1234);
        address newOwner = address(0x5678);
        address originalOwner = c.owner();

        // Attempt to call setOwner as nonAdmin
        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract reverts (ok=false) so owner stays originalOwner;
        // the buggy contract succeeds (ok=true) and sets owner to newOwner.
        // Assert that the call reverted and owner is unchanged (true for reference, false for bug)
        assertTrue(!ok && c.owner() == originalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deployer is admin
        // Call setOwner with a specific concrete address
        address newOwner = address(0xdead);
        c.setOwner(newOwner);
        // The reference contract sets owner = newOwner, buggy sets owner = address(0)
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        address admin = address(this);
        // The deployer (address(this)) is the admin; the original owner is also address(this)
        // Call setOwner; in reference it succeeds, in buggy it reverts
        vm.prank(admin);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        assertTrue(ok == true && c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call setOwner with a concrete address
        bool returnedValue = c.setOwner(address(0x123));
        // The reference returns true, the bug returns false
        assertTrue(returnedValue == true);
    }
}
